 async function bindSave(){if(!bindingDraft||!selectedShot||dirty){setError('Save the setup and select a shot before binding.');return;}const request:any={shot_id:selectedShot.id,expected_shot_revision:selectedShot.revision,binding_id:binding?.header.id||uid(),binding:copy(bindingDraft)};if(binding)request.revision=binding.header.revision;await reviewedAction('Review exact camera, version and timing',binding?'spatial.rebind-preview':'spatial.bind-preview',binding?'spatial.rebind':'spatial.bind',request,async v=>{setBinding(v);setBindingDraft(copy(v.version.binding_json));setMessage('Shot binding saved. Shot prose and duration are unchanged.');try{await props.refresh();}catch(e:any){setMessage('Binding saved; project refresh failed: '+e.message);}});}
